Meta.input_schema:
{
  "type": "object",
  "properties": {
    "action": { "type": "string", "description": "list the bundle's files or read one", "enum": ["list", "read"] },
    "skill_id": { "type": "string", "description": "Skill id" },
    "path": { "type": "string", "description": "File path within the bundle (read)" },
    "version": { "type": "integer", "description": "Skill version to read from; default the current version" },
    "kind": { "type": "string", "enum": ["reference", "asset", "script"], "description": "Filter the manifest by kind (list)" },
    "max_bytes": { "type": "integer", "description": "Reject a file larger than this (read)" },
    "format": { "type": "string", "enum": ["text", "base64"], "description": "Return content as text (default) or base64 for binary assets (read)" }
  },
  "required": ["action", "skill_id"],
  "additionalProperties": false
}

Meta.output_schema:
{
  "type": "string",
  "description": "Markdown. list -> the bundle's file manifest (path, kind, and size per file); read -> one file's contents (base64-wrapped when format=base64 or the asset is binary). Failures return no result and a typed tool error with a clear message."
}

Meta.input_schema:
{
  "type": "object",
  "properties": {
    "action": {
      "type": "string",
      "description": "What to do",
      "enum": ["list", "use", "activate", "deactivate", "save", "refine", "delete", "share", "unshare"]
    },
    "skill_id": { "type": "string", "description": "Skill id (use/activate/deactivate/refine/delete/share)" },
    "name": { "type": "string", "description": "Skill name (save)" },
    "description": { "type": "string", "description": "What the skill does + when to use it (save/refine)" },
    "body": { "type": "string", "description": "Markdown procedure (save/refine)" },
    "status": { "type": "string", "enum": ["active", "archived"], "description": "Archive or reactivate a skill (refine)" },
    "agent_id": { "type": "string", "description": "Scope the skill to an agent; omit for user-global" },
    "user_id": { "type": "string", "description": "Target user (share/unshare)" },
    "access_mask": { "type": "integer", "description": "Access bits to grant (share); default read" },
    "files": {
      "type": "array",
      "description": "Optional bundled files (save/refine). On refine, providing files fully replaces the prior set; omit to carry them forward.",
      "items": {
        "type": "object",
        "properties": {
          "path": { "type": "string", "description": "Path within the skill bundle, e.g. references/api.md or scripts/run.py" },
          "kind": { "type": "string", "enum": ["reference", "asset", "script"], "description": "Defaults from the path (scripts/ -> script, assets/ -> asset, else reference)" },
          "content": { "type": "string", "description": "File content (text, or base64 when encoding is base64)" },
          "encoding": { "type": "string", "enum": ["text", "base64"], "description": "Content encoding; default text" }
        },
        "required": ["path", "content"]
      }
    }
  },
  "required": ["action"],
  "additionalProperties": false
}

Meta.output_schema:
{
  "oneOf": [
    {
      "type": "string",
      "description": "Markdown or a short confirmation. list -> the available skills (name + description + skill_id); use -> the skill's full body plus a file manifest; save/refine/delete/share/unshare -> a one-line confirmation naming the skill_id (and user_id for share/unshare)."
    },
    {
      "type": "object",
      "description": "activate/deactivate result: a status message, plus a session-context control directive when the active skill set changed.",
      "properties": {
        "message": {"type": "string", "description": "Outcome of the activate or deactivate action."},
        "_control": {
          "type": "object",
          "description": "Runtime directive that persists the session's new active_skills set.",
          "properties": {"context": {"type": "object"}}
        }
      },
      "required": ["message"]
    }
  ],
  "description": "Successful tool result. Failures return no result and a typed tool error with a clear message."
}
